<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\ProvisionInstanceRequest; use App\Models\{Client,IkontrolInstance}; use App\Services\{AuditService,InstanceProvisioningService};
class ProvisioningController extends Controller { public function create(){return view('admin.provisioning.create',['clients'=>Client::whereActive(true)->orderBy('name')->get()]);} public function preflight(ProvisionInstanceRequest $r,InstanceProvisioningService $s){return response()->json($s->preflight($r->validated()['slug']));} public function store(ProvisionInstanceRequest $r,InstanceProvisioningService $s){$i=$s->provision($r->validated());return redirect()->route('instances.show',$i)->with($i->installation_status->value==='FAILED'?'error':'success',$i->installation_status->value==='FAILED'?'La preparación falló; revise la bitácora.':'Instalación preparada.');} public function retry(IkontrolInstance $instance,AuditService $a){$a->record('retry_instance','Reintento solicitado.',$instance);return redirect()->route('provisioning.create')->with('error','Revise los recursos parciales antes de un reintento.');} }
